func hostileDiffResult() Result {
	return Result{
		Base: "main", Head: "HEAD",
		Files: []FileChange{{
			Path: "deploy/" + hostileEntity + ".yaml", Status: "M", Language: "yaml",
			Changes: []EntityChange{
