   147	// escapedAt reports how the byte at index i must be treated: keep it (0), escape
   148	// just it (1), or escape it together with the byte that follows (2). Returning
   149	// the width is what lets the scan and the rewrite share one copy of the rules.
   150	func escapedAt[T text](data T, i int, keep layout) int {
   151		character := data[i]
   152		switch {
   153		case character == '\n' || character == '\t':
   154			if keep {
   155				return 0
   156			}
   157			return 1
   158		case character == '\r':
   159			// CRLF is the line ending of a Windows-authored file, not an overwrite.
   160			if keep && i+1 < len(data) && data[i+1] == '\n' {
   161				return 0
   162			}
   163			return 1
   164		case character < 0x20 || character == 0x7f:
   165			// C0 and DEL. ESC (0x1b) is the sequence introducer that matters most,
   166			// but BEL, backspace, and the cursor controls all rewrite what is seen.
   167			return 1
   168		case character == 0xc2 && i+1 < len(data) && data[i+1] >= 0x80 && data[i+1] <= 0x9f:
   169			// The C1 controls in their two-byte UTF-8 form. U+009B is CSI, which a
   170			// terminal in UTF-8 mode acts on exactly as it acts on ESC followed by
   171			// '['; escaping only C0 would leave that introducer reachable.
   172			return 2
   173		default:
   174			return 0
   175		}
   176	}
