   187	// appendEscaped writes data to dst with every control byte replaced by the Go
   188	// literal that denotes it, so a reader who meets the escape in a terminal or a
   189	// log sees the byte written the way source would write it.
   190	func appendEscaped[T text](dst []byte, data T, keep layout) []byte {
   191		for i := 0; i < len(data); i++ {
   192			switch escapedAt(data, i, keep) {
   193			case 1:
   194				dst = append(dst, '\\', 'x', hexDigits[data[i]>>4], hexDigits[data[i]&0x0f])
